"""Semantic version parsing, comparison, and range matching.

Versions follow Semantic Versioning 2.0.0: ``MAJOR.MINOR.PATCH``, then an
optional pre-release (``-`` followed by dot-separated identifiers) and an
optional build (``+`` followed by dot-separated identifiers). Identifiers
are non-empty and made of ASCII letters, digits, and hyphens. Numeric parts
(MAJOR, MINOR, PATCH, and all-digit pre-release identifiers) must not have
leading zeros. Anything else is invalid and raises ``ValueError``.

Precedence (``compare``) follows the SemVer 2.0.0 rules: compare MAJOR,
MINOR, and PATCH numerically; a version with a pre-release is lower than
the same version without one; pre-release identifiers are compared left to
right, all-digit ones numerically and the rest in ASCII order, with
all-digit identifiers lower than the rest, and a shorter list lower when
all its identifiers equal the start of a longer one. Build metadata is
ignored.

Ranges (``satisfies``) are one or more comparator sets joined by ``||``; a
version satisfies the range if it satisfies any set. A set is one or more
comparators separated by whitespace, all of which must hold. A comparator
is a full version optionally prefixed by an operator:

- ``=`` (or no operator), ``>``, ``>=``, ``<``, ``<=``: by precedence.
- ``^X.Y.Z``: at least ``X.Y.Z`` and below the next version that changes
  the leftmost non-zero part, i.e. ``^1.2.3`` is ``>=1.2.3 <2.0.0``,
  ``^0.2.3`` is ``>=0.2.3 <0.3.0``, and ``^0.0.3`` is ``>=0.0.3 <0.0.4``.
- ``~X.Y.Z``: at least ``X.Y.Z`` and below ``X.(Y+1).0``.

A version with a pre-release satisfies a set only if some comparator in
that set has a pre-release on the same MAJOR.MINOR.PATCH (so
``1.2.3-beta.2`` satisfies ``>=1.2.3-beta.1`` but not ``>=1.0.0``).
Invalid ranges raise ``ValueError``.
"""

from __future__ import annotations

import re
from dataclasses import dataclass


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


_NUMERIC = re.compile(r"(?:0|[1-9][0-9]*)")
_DIGITS = re.compile(r"[0-9]+")
_IDENTIFIER = re.compile(r"[0-9A-Za-z-]+")


def parse(text: str) -> Version:
    """Parse a version string."""
    if not isinstance(text, str):
        raise ValueError(f"invalid version: {text!r}")

    main, plus, build_text = text.partition("+")
    if plus:
        if not build_text:
            raise ValueError(f"invalid version: {text!r}")
        build = tuple(build_text.split("."))
        if any(not _IDENTIFIER.fullmatch(part) for part in build):
            raise ValueError(f"invalid version: {text!r}")
    else:
        build = ()

    core_text, dash, prerelease_text = main.partition("-")
    core = core_text.split(".")
    if len(core) != 3 or any(not _NUMERIC.fullmatch(part) for part in core):
        raise ValueError(f"invalid version: {text!r}")

    if dash:
        if not prerelease_text:
            raise ValueError(f"invalid version: {text!r}")
        prerelease = tuple(prerelease_text.split("."))
        for identifier in prerelease:
            if not _IDENTIFIER.fullmatch(identifier):
                raise ValueError(f"invalid version: {text!r}")
            if (
                _DIGITS.fullmatch(identifier)
                and len(identifier) > 1
                and identifier.startswith("0")
            ):
                raise ValueError(f"invalid version: {text!r}")
    else:
        prerelease = ()

    return Version(
        int(core[0]),
        int(core[1]),
        int(core[2]),
        prerelease=prerelease,
        build=build,
    )


def _coerce(value: str | Version) -> Version:
    if isinstance(value, Version):
        return value
    return parse(value)


def _is_numeric(identifier: str) -> bool:
    return bool(_DIGITS.fullmatch(identifier))


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    left = _coerce(a)
    right = _coerce(b)

    for attr in ("major", "minor", "patch"):
        lv = getattr(left, attr)
        rv = getattr(right, attr)
        if lv != rv:
            return -1 if lv < rv else 1

    if left.prerelease == right.prerelease:
        return 0
    if not left.prerelease:
        return 1
    if not right.prerelease:
        return -1

    for li, ri in zip(left.prerelease, right.prerelease):
        if li == ri:
            continue
        li_numeric = _is_numeric(li)
        ri_numeric = _is_numeric(ri)
        if li_numeric and ri_numeric:
            li_value = int(li)
            ri_value = int(ri)
            if li_value != ri_value:
                return -1 if li_value < ri_value else 1
            continue
        if li_numeric:
            return -1
        if ri_numeric:
            return 1
        return -1 if li < ri else 1

    if len(left.prerelease) == len(right.prerelease):
        return 0
    return -1 if len(left.prerelease) < len(right.prerelease) else 1


_OPERATORS = (">=", "<=", ">", "<", "=", "^", "~")


def _parse_comparator(token: str) -> tuple[str, Version]:
    for operator in _OPERATORS:
        if token.startswith(operator):
            rest = token[len(operator) :]
            if not rest:
                raise ValueError(f"invalid comparator: {token!r}")
            return operator, parse(rest)
    return "=", parse(token)


def _satisfies_comparator(version: Version, operator: str, target: Version) -> bool:
    result = compare(version, target)
    if operator == "=":
        return result == 0
    if operator == ">":
        return result > 0
    if operator == ">=":
        return result >= 0
    if operator == "<":
        return result < 0
    if operator == "<=":
        return result <= 0

    if operator == "^":
        if target.major > 0:
            upper = Version(target.major + 1, 0, 0)
        elif target.minor > 0:
            upper = Version(0, target.minor + 1, 0)
        else:
            upper = Version(0, 0, target.patch + 1)
    elif operator == "~":
        upper = Version(target.major, target.minor + 1, 0)
    else:  # pragma: no cover - guarded by _parse_comparator
        raise ValueError(f"invalid operator: {operator!r}")

    return result >= 0 and compare(version, upper) < 0


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    if not isinstance(range_, str):
        raise ValueError(f"invalid range: {range_!r}")

    sets: list[list[tuple[str, Version]]] = []
    for raw_set in range_.split("||"):
        tokens = raw_set.split()
        if not tokens:
            raise ValueError(f"invalid range: {range_!r}")
        sets.append([_parse_comparator(token) for token in tokens])

    candidate = _coerce(version)
    for comparators in sets:
        if candidate.prerelease:
            allowed = any(
                target.prerelease
                and (target.major, target.minor, target.patch)
                == (candidate.major, candidate.minor, candidate.patch)
                for _, target in comparators
            )
            if not allowed:
                continue
        if all(
            _satisfies_comparator(candidate, operator, target)
            for operator, target in comparators
        ):
            return True
    return False

"""Write and read Markdown (GitHub-flavored) pipe tables.

``format_table`` writes a header line, a delimiter line, and one line per
row, separated by ``\\n`` with no trailing newline. Every line is ``| ``,
then the column cells joined by `` | ``, then `` |``.

Cell text is ``str(value)``, or empty for ``None``, with each ``|``
escaped as ``\\|``. A row shorter than the header is padded with empty
cells; a longer one raises ``ValueError``. Each column is as wide as its
longest cell text (after escaping, and including the header), and at
least 3.

Cells are padded with spaces to the column width according to the
column's alignment: ``"left"`` or ``None`` pads on the right, ``"right"``
pads on the left, and ``"center"`` pads both sides equally, with any odd
space on the right. ``align`` gives one alignment per column (default all
``None``); any other value, or a list of the wrong length, raises
``ValueError``.

Delimiter cells are dashes filling the column width, with a colon replacing
the first dash for ``"left"``, the last for ``"right"``, and both for
``"center"`` (``:--``, ``--:``, ``:-:`` at width 3).

``parse_table`` reads such a table back, tolerating any padding and missing
leading or trailing pipes: it returns the header and the rows as lists of
stripped strings with ``\\|`` unescaped, and the alignment of each column
from the delimiter line (``None`` for plain dashes). Each delimiter cell
must be one or more dashes with an optional colon at either end. Text that
isn't a table (fewer than two lines, a bad delimiter line, or a delimiter
line or row with a different number of cells than the header) raises
``ValueError``.
"""

from __future__ import annotations

import re

_ALIGNMENTS = (None, "left", "right", "center")
_DELIMITER = re.compile(r"(:?)(-+)(:?)")


def _cell_text(value) -> str:
    text = "" if value is None else str(value)
    return text.replace("|", "\\|")


def _pad(text: str, width: int, alignment: str | None) -> str:
    extra = width - len(text)
    if alignment == "right":
        return " " * extra + text
    if alignment == "center":
        left = extra // 2
        return " " * left + text + " " * (extra - left)
    return text + " " * extra


def _delimiter(width: int, alignment: str | None) -> str:
    if alignment == "left":
        return ":" + "-" * (width - 1)
    if alignment == "right":
        return "-" * (width - 1) + ":"
    if alignment == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def _split_row(line: str) -> list[str]:
    line = line.strip()
    cells: list[str] = []
    current: list[str] = []

    i = 0
    while i < len(line):
        character = line[i]
        if character == "\\" and i + 1 < len(line) and line[i + 1] == "|":
            current.append("|")
            i += 2
        elif character == "|":
            cells.append("".join(current))
            current = []
            i += 1
        else:
            current.append(character)
            i += 1
    cells.append("".join(current))

    if cells and cells[0] == "":
        cells.pop(0)
    if cells and cells[-1] == "":
        cells.pop()
    return [cell.strip() for cell in cells]


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    columns = len(header)

    if align is None:
        alignments: list[str | None] = [None] * columns
    else:
        try:
            alignments = list(align)
        except TypeError:
            raise ValueError("align must be a list of alignments") from None
        if len(alignments) != columns:
            raise ValueError("align must have one entry per column")
        for alignment in alignments:
            if alignment not in _ALIGNMENTS:
                raise ValueError(f"invalid alignment: {alignment!r}")

    header_cells = [_cell_text(value) for value in header]

    row_cells: list[list[str]] = []
    for row in rows:
        if len(row) > columns:
            raise ValueError("row has more cells than the header")
        cells = [_cell_text(value) for value in row]
        cells.extend([""] * (columns - len(cells)))
        row_cells.append(cells)

    widths = [
        max([3, len(header_cells[column])] + [len(row[column]) for row in row_cells])
        for column in range(columns)
    ]

    lines = []
    lines.append(
        "| "
        + " | ".join(
            _pad(cell, widths[column], alignments[column])
            for column, cell in enumerate(header_cells)
        )
        + " |"
    )
    lines.append(
        "| "
        + " | ".join(
            _delimiter(widths[column], alignments[column])
            for column in range(columns)
        )
        + " |"
    )
    for cells in row_cells:
        lines.append(
            "| "
            + " | ".join(
                _pad(cell, widths[column], alignments[column])
                for column, cell in enumerate(cells)
            )
            + " |"
        )
    return "\n".join(lines)


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    if len(lines) < 2:
        raise ValueError("not a table: fewer than two lines")

    header = _split_row(lines[0])
    delimiter_cells = _split_row(lines[1])
    if len(delimiter_cells) != len(header):
        raise ValueError("delimiter line has a different number of cells")

    alignments: list[str | None] = []
    for cell in delimiter_cells:
        match = _DELIMITER.fullmatch(cell)
        if match is None:
            raise ValueError(f"bad delimiter cell: {cell!r}")
        leading, _dashes, trailing = match.groups()
        if leading and trailing:
            alignments.append("center")
        elif leading:
            alignments.append("left")
        elif trailing:
            alignments.append("right")
        else:
            alignments.append(None)

    rows: list[list[str]] = []
    for line in lines[2:]:
        cells = _split_row(line)
        if len(cells) != len(header):
            raise ValueError("row has a different number of cells than the header")
        rows.append(cells)

    return header, rows, alignments

"""Find when a cron schedule next fires.

An expression has five whitespace-separated fields: minute (0-59), hour
(0-23), day of month (1-31), month (1-12), and day of week (0-7, where both
0 and 7 are Sunday). Each field is a comma-separated list of items, where
an item is:

- ``*``, every value in the field's range,
- a value ``N``,
- a range ``A-B`` (inclusive, with ``A <= B``),
- any of those followed by ``/S`` for every ``S``-th value starting at the
  first one (``*/15`` in the minute field is 0, 15, 30, 45; ``10-30/10`` is
  10, 20, 30; ``5/20`` is 5, 25, 45, i.e. from 5 to the end of the range).

Months may also be given by the names ``JAN``-``DEC`` and days of the week
by ``SUN``-``SAT``, in any case, including in ranges. A value outside its
field's range, a malformed item, or a field count other than five raises
``ValueError``.

As in Vixie cron, when both the day-of-month and day-of-week fields are
restricted (neither is exactly ``*``), a day matches if it matches either
one; otherwise it must match both.

Times are naive datetimes. ``next_run`` returns the earliest matching time
strictly after ``after``, with seconds and microseconds zero. If nothing
matches within the next five years (e.g. ``0 0 30 2 *``), it raises
``ValueError``.
"""

from __future__ import annotations

import calendar
import re
from datetime import date, datetime, time, timedelta

_MONTH_NAMES = {
    name: number
    for number, name in enumerate(
        ("JAN", "FEB", "MAR", "APR", "MAY", "JUN",
         "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"),
        1,
    )
}

_DOW_NAMES = {
    name: number
    for number, name in enumerate(
        ("SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT")
    )
}

_DIGITS = re.compile(r"[0-9]+")


def _parse_value(token: str, low: int, high: int, names: dict[str, int] | None) -> int:
    if names is not None and token.upper() in names:
        value = names[token.upper()]
    else:
        if not _DIGITS.fullmatch(token):
            raise ValueError(f"invalid value: {token!r}")
        value = int(token)

    if value < low or value > high:
        raise ValueError(f"value out of range: {token!r}")
    return value


def _parse_item(
    item: str, low: int, high: int, names: dict[str, int] | None
) -> set[int]:
    if not item:
        raise ValueError("empty cron item")

    base, slash, step_text = item.partition("/")
    if slash:
        if "/" in step_text or not _DIGITS.fullmatch(step_text):
            raise ValueError(f"invalid step: {item!r}")
        step = int(step_text)
        if step <= 0:
            raise ValueError(f"invalid step: {item!r}")
    else:
        step = 1

    if base == "*":
        start, end = low, high
        if not slash:
            return set(range(start, end + 1))
    elif "-" in base:
        if base.count("-") != 1:
            raise ValueError(f"invalid range: {item!r}")
        first, last = base.split("-")
        start = _parse_value(first, low, high, names)
        end = _parse_value(last, low, high, names)
        if start > end:
            raise ValueError(f"invalid range: {item!r}")
    else:
        value = _parse_value(base, low, high, names)
        if not slash:
            return {value}
        start, end = value, high

    return set(range(start, end + 1, step))


def _parse_field(
    field: str, low: int, high: int, names: dict[str, int] | None = None
) -> set[int]:
    values: set[int] = set()
    for item in field.split(","):
        values.update(_parse_item(item, low, high, names))
    return values


def _add_years(moment: datetime, years: int) -> datetime:
    year = moment.year + years
    last_day = calendar.monthrange(year, moment.month)[1]
    return moment.replace(year=year, day=min(moment.day, last_day))


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    if not isinstance(expression, str):
        raise ValueError(f"invalid cron expression: {expression!r}")

    fields = expression.split()
    if len(fields) != 5:
        raise ValueError(f"invalid cron expression: {expression!r}")

    minute_field, hour_field, dom_field, month_field, dow_field = fields

    minutes = _parse_field(minute_field, 0, 59)
    hours = _parse_field(hour_field, 0, 23)
    days_of_month = _parse_field(dom_field, 1, 31)
    months = _parse_field(month_field, 1, 12, _MONTH_NAMES)
    days_of_week = {
        0 if value == 7 else value
        for value in _parse_field(dow_field, 0, 7, _DOW_NAMES)
    }

    dom_restricted = dom_field != "*"
    dow_restricted = dow_field != "*"

    first = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    limit = _add_years(after, 5)

    ordered_hours = sorted(hours)
    ordered_minutes = sorted(minutes)

    current = first.date()
    last_date = limit.date()

    while current <= last_date:
        if current.month in months:
            dom_matches = current.day in days_of_month
            # Python's Monday is 0; cron's Sunday is 0.
            cron_dow = (current.weekday() + 1) % 7
            dow_matches = cron_dow in days_of_week

            if dom_restricted and dow_restricted:
                day_matches = dom_matches or dow_matches
            else:
                day_matches = dom_matches and dow_matches

            if day_matches:
                for hour in ordered_hours:
                    for minute in ordered_minutes:
                        candidate = datetime.combine(
                            current, time(hour, minute), tzinfo=after.tzinfo
                        )
                        if candidate < first:
                            continue
                        if candidate > limit:
                            raise ValueError(
                                f"no matching time within five years: {expression!r}"
                            )
                        return candidate

        current += timedelta(days=1)

    raise ValueError(f"no matching time within five years: {expression!r}")

